function submitEditor(form){let v=Object.fromEntries(new FormData(form).entries()),[kind,id]=ui.sheet.split('|');if(kind==='task'){if(!v.title?.trim())return toast('Введи название');let t=data.tasks.find(x=>String(x.id)===id);if(!t){t={id:Math.max(0,...data.tasks.map(x=>Number(x.id)||0))+1};data.tasks.push(t)}Object.assign(t,{sub:v.sub,title:v.title.trim(),date:v.date,status:v.status,note:v.note})}else if(kind==='exam'){if(!v.subject?.trim())return toast('Введи предмет');let x=data.exams.find(x=>String(x.id)===id);if(!x){x={id:'exam_'+Date.now()};data.exams.push(x)}Object.assign(x,{subject:v.subject.trim(),type:v.type,date:v.date,time:v.time,room:v.room,status:v.status})}else if(kind==='change'){data.changes=data.changes.filter(c=>!(c.date===dateISO(ui.date)&&Number(c.index)===Number(v.index)));data.changes.push({date:dateISO(ui.date),index:Number(v.index),mode:v.mode,start:v.start,end:v.end,room:v.room})}else if(kind==='name')data.name=v.name.trim().slice(0,70)||'Александр';persist();ui.sheet=null;render();toast('Сохранено')}
